import { useMemo, useState, type ReactNode } from 'react';
import { Link } from 'react-router-dom';
import type {
  Category,
  PunishmentTemplate,
  PunishmentTrigger,
  Reward,
  RewardTrigger,
  Task,
  TaskFrequency,
  UserRole,
} from '../types';
import { useAppStore } from '../hooks/useAppStore';

function newId(prefix: string): string {
  return `${prefix}-${Date.now()}`;
}

const ADMIN_TABS = [
  { id: 'categories' as const, label: 'Categories' },
  { id: 'tasks' as const, label: 'Tasks' },
  { id: 'rewards' as const, label: 'Rewards' },
  { id: 'punishments' as const, label: 'Punishments' },
  { id: 'users' as const, label: 'Users' },
];

const CATEGORY_COLORS = [
  '#f9a8d4',
  '#e879f9',
  '#c084fc',
  '#a78bfa',
  '#818cf8',
  '#4ade80',
  '#fb923c',
  '#f87171',
];

const LEVELS = [1, 2, 3, 4, 5] as const;
const FREQUENCIES: { value: TaskFrequency; label: string }[] = [
  { value: 'daily', label: 'Daily' },
  { value: 'weekly', label: 'Weekly' },
  { value: 'once', label: 'One-time' },
];

type AdminTabId = (typeof ADMIN_TABS)[number]['id'];

export function Admin() {
  const [tab, setTab] = useState<AdminTabId>('categories');

  return (
    <div className="page page--admin">
      <header className="page-header">
        <h2>Admin</h2>
        <p className="muted">
          Manage categories, tasks, rewards, punishment templates, and users.
        </p>
      </header>

      <nav className="admin-tabs" aria-label="Admin sections">
        {ADMIN_TABS.map(({ id, label }) => (
          <button
            key={id}
            type="button"
            role="tab"
            aria-selected={tab === id}
            className={tab === id ? 'admin-tab admin-tab--active' : 'admin-tab'}
            onClick={() => setTab(id)}
          >
            {label}
          </button>
        ))}
      </nav>

      <div className="admin-tab-panel" role="tabpanel">
        {tab === 'categories' && <CategoryAdmin />}
        {tab === 'tasks' && <TaskAdmin />}
        {tab === 'rewards' && <RewardAdmin />}
        {tab === 'punishments' && <PunishmentTemplateAdmin />}
        {tab === 'users' && <UserAdmin />}
      </div>

      <div className="btn-row admin-footer">
        <Link to="/" className="btn btn--ghost">
          Back to app
        </Link>
      </div>
    </div>
  );
}

function AdminPanel({
  list,
  form,
}: {
  list: ReactNode;
  form: ReactNode;
}) {
  return (
    <div className="admin-panel">
      <div className="admin-panel__list">{list}</div>
      <div className="admin-panel__form">{form}</div>
    </div>
  );
}

function AdminListHeader({
  title,
  count,
  search,
  onSearchChange,
  filter,
}: {
  title: string;
  count: number;
  search: string;
  onSearchChange: (v: string) => void;
  filter?: ReactNode;
}) {
  return (
    <div className="admin-list-header">
      <div className="admin-list-header__top">
        <h3 className="admin-list-header__title">{title}</h3>
        <span className="admin-list-header__count" aria-live="polite">
          {count}
        </span>
      </div>
      <div className="admin-list-header__tools">
        <label className="admin-search">
          <span className="visually-hidden">Search {title.toLowerCase()}</span>
          <input
            type="search"
            placeholder="Search…"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
            aria-label={`Search ${title.toLowerCase()}`}
          />
        </label>
        {filter}
      </div>
    </div>
  );
}

function AdminEmpty({ title, hint }: { title: string; hint: string }) {
  return (
    <div className="admin-empty">
      <p className="admin-empty__title">{title}</p>
      <p className="admin-empty__hint">{hint}</p>
    </div>
  );
}

function AdminItemCard({
  selected,
  title,
  meta,
  onEdit,
  onDelete,
  deleteLabel,
}: {
  selected?: boolean;
  title: string;
  meta?: string;
  onEdit: () => void;
  onDelete: () => void;
  deleteLabel?: string;
}) {
  return (
    <article
      className={
        selected ? 'admin-item admin-item--selected' : 'admin-item'
      }
    >
      <button
        type="button"
        className="admin-item__main"
        onClick={onEdit}
        aria-pressed={selected}
      >
        <span className="admin-item__title">{title}</span>
        {meta && <span className="admin-item__meta">{meta}</span>}
      </button>
      <div className="admin-item__actions">
        <button
          type="button"
          className="btn btn--ghost btn--small"
          onClick={onEdit}
        >
          Edit
        </button>
        <button
          type="button"
          className="btn btn--ghost btn--small btn--danger-text"
          onClick={onDelete}
        >
          {deleteLabel ?? 'Delete'}
        </button>
      </div>
    </article>
  );
}

function FormField({
  label,
  htmlFor,
  hint,
  required,
  error,
  children,
}: {
  label: string;
  htmlFor?: string;
  hint?: string;
  required?: boolean;
  error?: string;
  children: ReactNode;
}) {
  return (
    <div className={`admin-field${error ? ' admin-field--error' : ''}`}>
      <label className="admin-field__label" htmlFor={htmlFor}>
        {label}
        {required && (
          <span className="admin-field__required" aria-hidden="true">
            *
          </span>
        )}
      </label>
      {hint && <p className="admin-field__hint">{hint}</p>}
      {children}
      {error && (
        <p className="admin-field__error" role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

function FormGroup({ legend, children }: { legend: string; children: ReactNode }) {
  return (
    <fieldset className="admin-form-group">
      <legend className="admin-form-group__legend">{legend}</legend>
      {children}
    </fieldset>
  );
}

function ChipSelect<T extends string | number>({
  label,
  options,
  value,
  onChange,
}: {
  label: string;
  options: { value: T; label: string }[];
  value: T;
  onChange: (v: T) => void;
}) {
  return (
    <div className="admin-chips" role="group" aria-label={label}>
      {options.map((opt) => (
        <button
          key={String(opt.value)}
          type="button"
          className={
            value === opt.value ? 'admin-chip admin-chip--active' : 'admin-chip'
          }
          aria-pressed={value === opt.value}
          onClick={() => onChange(opt.value)}
        >
          {opt.label}
        </button>
      ))}
    </div>
  );
}

function RadioRow<T extends string>({
  label,
  name,
  options,
  value,
  onChange,
}: {
  label: string;
  name: string;
  options: { value: T; label: string; hint?: string }[];
  value: T;
  onChange: (v: T) => void;
}) {
  return (
    <div className="admin-radio-row" role="radiogroup" aria-label={label}>
      {options.map((opt) => (
        <label key={opt.value} className="admin-radio">
          <input
            type="radio"
            name={name}
            value={opt.value}
            checked={value === opt.value}
            onChange={() => onChange(opt.value)}
          />
          <span className="admin-radio__label">{opt.label}</span>
          {opt.hint && <span className="admin-radio__hint">{opt.hint}</span>}
        </label>
      ))}
    </div>
  );
}

function FormActions({
  editing,
  entityLabel,
  onSubmit,
  onClear,
  disabled,
}: {
  editing: boolean;
  entityLabel: string;
  onSubmit: () => void;
  onClear: () => void;
  disabled?: boolean;
}) {
  return (
    <div className="admin-form-actions">
      <button
        type="button"
        className="btn btn--primary"
        onClick={onSubmit}
        disabled={disabled}
      >
        {editing ? `Save ${entityLabel}` : `Create ${entityLabel}`}
      </button>
      <button type="button" className="btn btn--ghost" onClick={onClear}>
        {editing ? 'Cancel' : 'Clear'}
      </button>
    </div>
  );
}

function StatusBanner({ message, variant }: { message: string; variant?: 'ok' | 'err' }) {
  if (!message) return null;
  return (
    <p
      className={variant === 'err' ? 'admin-banner admin-banner--error' : 'admin-banner'}
      role="status"
    >
      {message}
    </p>
  );
}

function emptyCategoryDraft(): Category {
  return {
    id: '',
    name: '',
    icon: '✨',
    color: '#f9a8d4',
    description: '',
    imageUrl: undefined,
  };
}

function CategoryAdmin() {
  const { state, addCategory, updateCategory, deleteCategory } = useAppStore();
  const [draft, setDraft] = useState<Category>(emptyCategoryDraft());
  const [search, setSearch] = useState('');
  const [message, setMessage] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return state.categories;
    return state.categories.filter(
      (c) =>
        c.name.toLowerCase().includes(q) ||
        c.description.toLowerCase().includes(q),
    );
  }, [state.categories, search]);

  const validate = () => {
    const next: Record<string, string> = {};
    if (!draft.name.trim()) next.name = 'Name is required.';
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const clearForm = () => {
    setDraft(emptyCategoryDraft());
    setErrors({});
  };

  const submit = () => {
    if (!validate()) return;
    const cat = { ...draft, id: draft.id || newId('cat') };
    if (state.categories.some((c) => c.id === cat.id)) updateCategory(cat);
    else addCategory(cat);
    clearForm();
    setMessage('Category saved.');
  };

  const remove = (id: string) => {
    if (!window.confirm('Delete this category and all its tasks?')) return;
    deleteCategory(id);
    if (draft.id === id) clearForm();
    setMessage('Category deleted.');
  };

  const imagePreview =
    draft.imageUrl?.startsWith('http') || draft.imageUrl?.startsWith('data:')
      ? draft.imageUrl
      : null;

  const list = (
    <>
      <AdminListHeader
        title="Categories"
        count={filtered.length}
        search={search}
        onSearchChange={setSearch}
      />
      <div className="admin-list">
        {filtered.length === 0 ? (
          <AdminEmpty
            title={search ? 'No matches' : 'No categories yet'}
            hint={
              search
                ? 'Try a different search term.'
                : 'Use the form to create your first category.'
            }
          />
        ) : (
          filtered.map((c) => (
            <AdminItemCard
              key={c.id}
              selected={draft.id === c.id}
              title={`${c.icon} ${c.name}`}
              meta={c.description || 'No description'}
              onEdit={() => {
                setDraft(c);
                setErrors({});
              }}
              onDelete={() => remove(c.id)}
            />
          ))
        )}
      </div>
    </>
  );

  const form = (
    <section className="card admin-form-card">
      <h3 className="admin-form-card__title">
        {draft.id ? 'Edit category' : 'New category'}
      </h3>
      <StatusBanner message={message} />

      <FormGroup legend="Identity">
        <FormField label="Name" htmlFor="cat-name" required error={errors.name}>
          <input
            id="cat-name"
            value={draft.name}
            onChange={(e) => {
              setDraft({ ...draft, name: e.target.value });
              if (errors.name) setErrors((p) => ({ ...p, name: '' }));
            }}
          />
        </FormField>
        <FormField
          label="Icon"
          htmlFor="cat-icon"
          hint="Emoji shown in lists and navigation."
        >
          <input
            id="cat-icon"
            value={draft.icon}
            onChange={(e) => setDraft({ ...draft, icon: e.target.value })}
            maxLength={4}
          />
        </FormField>
        <FormField label="Color" hint="Pick a preset or use the custom picker.">
          <div className="admin-color-row">
            <div className="admin-swatches" role="group" aria-label="Color presets">
              {CATEGORY_COLORS.map((color) => (
                <button
                  key={color}
                  type="button"
                  className={
                    draft.color === color
                      ? 'admin-swatch admin-swatch--active'
                      : 'admin-swatch'
                  }
                  style={{ background: color }}
                  aria-label={`Color ${color}`}
                  aria-pressed={draft.color === color}
                  onClick={() => setDraft({ ...draft, color })}
                />
              ))}
            </div>
            <input
              type="color"
              className="admin-color-input"
              aria-label="Custom color"
              value={draft.color}
              onChange={(e) => setDraft({ ...draft, color: e.target.value })}
            />
          </div>
        </FormField>
      </FormGroup>

      <FormGroup legend="Details">
        <FormField label="Description" htmlFor="cat-desc">
          <textarea
            id="cat-desc"
            rows={3}
            value={draft.description}
            onChange={(e) => setDraft({ ...draft, description: e.target.value })}
          />
        </FormField>
        <FormField
          label="Image URL"
          htmlFor="cat-image"
          hint="Optional. Shown on the category page; you can also set it there."
        >
          <input
            id="cat-image"
            type="url"
            placeholder="https://…"
            value={draft.imageUrl?.startsWith('http') ? draft.imageUrl : ''}
            onChange={(e) =>
              setDraft({
                ...draft,
                imageUrl: e.target.value.trim() || undefined,
              })
            }
          />
          {imagePreview && (
            <div className="admin-image-preview">
              <img src={imagePreview} alt="" />
            </div>
          )}
        </FormField>
      </FormGroup>

      <FormActions
        editing={!!draft.id}
        entityLabel="category"
        onSubmit={submit}
        onClear={() => {
          clearForm();
          setMessage('');
        }}
      />
    </section>
  );

  return <AdminPanel list={list} form={form} />;
}

function emptyTaskDraft(categoryId: string): Task {
  return {
    id: '',
    title: '',
    description: '',
    categoryId,
    minLevel: 1,
    xpReward: 10,
    frequency: 'daily',
  };
}

function TaskAdmin() {
  const { state, addTask, updateTask, deleteTask } = useAppStore();
  const defaultCat = state.categories[0]?.id ?? '';
  const [draft, setDraft] = useState<Task>(() => emptyTaskDraft(defaultCat));
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [message, setMessage] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return state.tasks.filter((t) => {
      if (filterCategory && t.categoryId !== filterCategory) return false;
      if (!q) return true;
      return (
        t.title.toLowerCase().includes(q) ||
        t.description.toLowerCase().includes(q)
      );
    });
  }, [state.tasks, search, filterCategory]);

  const categoryName = (id: string) =>
    state.categories.find((c) => c.id === id)?.name ?? 'Unknown';

  if (state.categories.length === 0) {
    return (
      <AdminEmpty
        title="No categories yet"
        hint="Create at least one category before adding tasks."
      />
    );
  }

  const validate = () => {
    const next: Record<string, string> = {};
    if (!draft.title.trim()) next.title = 'Title is required.';
    if (!draft.categoryId) next.categoryId = 'Select a category.';
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const clearForm = () => {
    setDraft(emptyTaskDraft(state.categories[0]?.id ?? ''));
    setErrors({});
  };

  const submit = () => {
    if (!validate()) return;
    const task = { ...draft, id: draft.id || newId('task') };
    if (state.tasks.some((t) => t.id === task.id)) updateTask(task);
    else addTask(task);
    clearForm();
    setMessage('Task saved.');
  };

  const remove = (id: string) => {
    if (!window.confirm('Delete this task?')) return;
    deleteTask(id);
    if (draft.id === id) clearForm();
    setMessage('Task deleted.');
  };

  const list = (
    <>
      <AdminListHeader
        title="Tasks"
        count={filtered.length}
        search={search}
        onSearchChange={setSearch}
        filter={
          <select
            className="admin-filter-select"
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value)}
            aria-label="Filter by category"
          >
            <option value="">All categories</option>
            {state.categories.map((c) => (
              <option key={c.id} value={c.id}>
                {c.icon} {c.name}
              </option>
            ))}
          </select>
        }
      />
      <div className="admin-list">
        {filtered.length === 0 ? (
          <AdminEmpty
            title={search || filterCategory ? 'No matches' : 'No tasks yet'}
            hint={
              search || filterCategory
                ? 'Adjust search or category filter.'
                : 'Use the form to add a task to the library.'
            }
          />
        ) : (
          filtered.map((t) => (
            <AdminItemCard
              key={t.id}
              selected={draft.id === t.id}
              title={t.title}
              meta={`${categoryName(t.categoryId)} · L${t.minLevel} · ${t.xpReward} XP · ${t.frequency}`}
              onEdit={() => {
                setDraft(t);
                setErrors({});
              }}
              onDelete={() => remove(t.id)}
            />
          ))
        )}
      </div>
    </>
  );

  const form = (
    <section className="card admin-form-card">
      <h3 className="admin-form-card__title">
        {draft.id ? 'Edit task' : 'New task'}
      </h3>
      <StatusBanner message={message} variant={errors.categoryId ? 'err' : undefined} />

      <FormGroup legend="Basics">
        <FormField label="Title" htmlFor="task-title" required error={errors.title}>
          <input
            id="task-title"
            value={draft.title}
            onChange={(e) => {
              setDraft({ ...draft, title: e.target.value });
              if (errors.title) setErrors((p) => ({ ...p, title: '' }));
            }}
          />
        </FormField>
        <FormField label="Description" htmlFor="task-desc">
          <textarea
            id="task-desc"
            rows={3}
            value={draft.description}
            onChange={(e) => setDraft({ ...draft, description: e.target.value })}
          />
        </FormField>
        <FormField
          label="Category"
          htmlFor="task-cat"
          required
          error={errors.categoryId}
        >
          <select
            id="task-cat"
            value={draft.categoryId || state.categories[0]?.id}
            onChange={(e) => {
              setDraft({ ...draft, categoryId: e.target.value });
              if (errors.categoryId) setErrors((p) => ({ ...p, categoryId: '' }));
            }}
          >
            {state.categories.map((c) => (
              <option key={c.id} value={c.id}>
                {c.icon} {c.name}
              </option>
            ))}
          </select>
        </FormField>
      </FormGroup>

      <FormGroup legend="Rules">
        <FormField label="Minimum level" hint="Players must reach this level to unlock the task.">
          <ChipSelect
            label="Minimum level"
            options={LEVELS.map((n) => ({ value: n, label: `L${n}` }))}
            value={draft.minLevel}
            onChange={(minLevel) => setDraft({ ...draft, minLevel })}
          />
        </FormField>
        <FormField label="XP reward" htmlFor="task-xp">
          <input
            id="task-xp"
            type="number"
            min={5}
            value={draft.xpReward}
            onChange={(e) =>
              setDraft({ ...draft, xpReward: Number(e.target.value) })
            }
          />
        </FormField>
        <FormField label="Frequency">
          <RadioRow
            label="Task frequency"
            name="task-frequency"
            options={FREQUENCIES}
            value={draft.frequency}
            onChange={(frequency) => setDraft({ ...draft, frequency })}
          />
        </FormField>
        <FormField
          label="Duration (minutes)"
          htmlFor="task-duration"
          hint="Optional. For timed activities."
        >
          <input
            id="task-duration"
            type="number"
            min={1}
            placeholder="Optional"
            value={draft.durationMinutes ?? ''}
            onChange={(e) =>
              setDraft({
                ...draft,
                durationMinutes: e.target.value
                  ? Number(e.target.value)
                  : undefined,
              })
            }
          />
        </FormField>
      </FormGroup>

      <FormActions
        editing={!!draft.id}
        entityLabel="task"
        onSubmit={submit}
        onClear={() => {
          clearForm();
          setMessage('');
        }}
      />
    </section>
  );

  return <AdminPanel list={list} form={form} />;
}

type RewardKind = 'shop' | 'badge';
type BadgeUnlock = 'streak' | 'level';

function emptyRewardDraft(): Reward {
  return {
    id: '',
    title: '',
    description: '',
    cost: 50,
  };
}

function RewardAdmin() {
  const { state, addReward, updateReward, deleteReward } = useAppStore();
  const [draft, setDraft] = useState<Reward>(emptyRewardDraft());
  const [kind, setKind] = useState<RewardKind>('shop');
  const [badgeUnlock, setBadgeUnlock] = useState<BadgeUnlock>('streak');
  const [streakDays, setStreakDays] = useState(7);
  const [levelTarget, setLevelTarget] = useState(2);
  const [search, setSearch] = useState('');
  const [message, setMessage] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return state.rewards;
    return state.rewards.filter(
      (r) =>
        r.title.toLowerCase().includes(q) ||
        r.description.toLowerCase().includes(q),
    );
  }, [state.rewards, search]);

  const loadDraft = (reward: Reward) => {
    setDraft(reward);
    if (reward.autoTrigger?.type === 'streak') {
      setKind('badge');
      setBadgeUnlock('streak');
      setStreakDays(reward.autoTrigger.days);
    } else if (reward.autoTrigger?.type === 'level') {
      setKind('badge');
      setBadgeUnlock('level');
      setLevelTarget(reward.autoTrigger.level);
    } else {
      setKind('shop');
    }
    setErrors({});
  };

  const buildReward = (): Reward => {
    const base: Reward = {
      id: draft.id || newId('reward'),
      title: draft.title.trim(),
      description: draft.description.trim(),
    };
    if (kind === 'shop') {
      return { ...base, cost: draft.cost ?? 50, autoTrigger: undefined };
    }
    const trigger: RewardTrigger =
      badgeUnlock === 'streak'
        ? { type: 'streak', days: streakDays }
        : { type: 'level', level: levelTarget };
    return { ...base, cost: undefined, autoTrigger: trigger };
  };

  const validate = () => {
    const next: Record<string, string> = {};
    if (!draft.title.trim()) next.title = 'Title is required.';
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const clearForm = () => {
    setDraft(emptyRewardDraft());
    setKind('shop');
    setBadgeUnlock('streak');
    setStreakDays(7);
    setLevelTarget(2);
    setErrors({});
  };

  const submit = () => {
    if (!validate()) return;
    const reward = buildReward();
    if (state.rewards.some((r) => r.id === reward.id)) updateReward(reward);
    else addReward(reward);
    clearForm();
    setMessage('Reward saved.');
  };

  const remove = (id: string) => {
    if (!window.confirm('Delete this reward from the catalog?')) return;
    deleteReward(id);
    if (draft.id === id) clearForm();
    setMessage('Reward deleted.');
  };

  const rewardMeta = (r: Reward) => {
    if (r.cost != null) return `${r.cost} points · Shop`;
    if (r.autoTrigger?.type === 'streak')
      return `Badge · ${r.autoTrigger.days}-day streak`;
    if (r.autoTrigger?.type === 'level')
      return `Badge · Level ${r.autoTrigger.level}`;
    return 'Badge';
  };

  const list = (
    <>
      <AdminListHeader
        title="Rewards"
        count={filtered.length}
        search={search}
        onSearchChange={setSearch}
      />
      <p className="admin-list-intro muted">
