          filtered.map((r) => (
            <AdminItemCard
              key={r.id}
              selected={draft.id === r.id}
              title={r.title}
              meta={rewardMeta(r)}
              onEdit={() => loadDraft(r)}
              onDelete={() => remove(r.id)}
            />
          ))
        )}
