    </>
  );

  const form = (
    <section className="card admin-form-card">
      <h3 className="admin-form-card__title">
        {draft.id ? 'Edit reward' : 'New reward'}
      </h3>
      <StatusBanner message={message} />

      <FormGroup legend="Basics">
        <FormField label="Title" htmlFor="reward-title" required error={errors.title}>
          <input
            id="reward-title"
            value={draft.title}
            onChange={(e) => {
              setDraft({ ...draft, title: e.target.value });
              if (errors.title) setErrors((p) => ({ ...p, title: '' }));
            }}
          />
        </FormField>
        <FormField label="Description" htmlFor="reward-desc">
          <textarea
            id="reward-desc"
            rows={3}
            value={draft.description}
            onChange={(e) => setDraft({ ...draft, description: e.target.value })}
          />
        </FormField>
      </FormGroup>

      <FormGroup legend="Type">
        <FormField label="Reward type">
          <RadioRow
            label="Reward type"
            name="reward-kind"
            options={[
              { value: 'shop' as const, label: 'Shop', hint: 'Costs points' },
              {
                value: 'badge' as const,
                label: 'Badge',
                hint: 'Unlocks automatically',
              },
            ]}
            value={kind}
            onChange={setKind}
          />
        </FormField>
        {kind === 'shop' ? (
          <FormField label="Point cost" htmlFor="reward-cost">
            <input
              id="reward-cost"
              type="number"
              min={1}
              value={draft.cost ?? 50}
              onChange={(e) =>
                setDraft({ ...draft, cost: Number(e.target.value) })
              }
            />
          </FormField>
        ) : (
          <>
            <FormField label="Unlock condition">
              <RadioRow
                label="Badge unlock"
                name="badge-unlock"
                options={[
                  { value: 'streak' as const, label: 'Streak' },
                  { value: 'level' as const, label: 'Level' },
                ]}
                value={badgeUnlock}
                onChange={setBadgeUnlock}
              />
            </FormField>
            {badgeUnlock === 'streak' ? (
              <FormField label="Streak days" htmlFor="reward-streak">
                <input
                  id="reward-streak"
                  type="number"
                  min={1}
