                />
              </FormField>
            )}
          </>
        )}
      </FormGroup>

      <FormActions
        editing={!!draft.id}
        entityLabel="reward"
        onSubmit={submit}
        onClear={() => {
          clearForm();
          setMessage('');
        }}
      />
    </section>
  );

  return <AdminPanel list={list} form={form} />;
}

function emptyPunishmentDraft(): PunishmentTemplate {
  return {
    id: '',
    title: '',
    description: '',
    trigger: { type: 'quota_miss' },
    pointsLost: 10,
  };
}

function PunishmentTemplateAdmin() {
  const {
    state,
    addPunishmentTemplate,
    updatePunishmentTemplate,
    deletePunishmentTemplate,
  } = useAppStore();
  const [draft, setDraft] = useState<PunishmentTemplate>(emptyPunishmentDraft());
  const [search, setSearch] = useState('');
  const [message, setMessage] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return state.punishmentTemplates;
    return state.punishmentTemplates.filter(
      (t) =>
        t.title.toLowerCase().includes(q) ||
        t.description.toLowerCase().includes(q),
    );
  }, [state.punishmentTemplates, search]);

  const validate = () => {
    const next: Record<string, string> = {};
    if (!draft.title.trim()) next.title = 'Title is required.';
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const clearForm = () => {
    setDraft(emptyPunishmentDraft());
    setErrors({});
  };

  const submit = () => {
    if (!validate()) return;
    const tpl = { ...draft, id: draft.id || newId('pun-tpl') };
    if (state.punishmentTemplates.some((t) => t.id === tpl.id)) {
      updatePunishmentTemplate(tpl);
    } else {
      addPunishmentTemplate(tpl);
    }
    clearForm();
    setMessage('Punishment template saved.');
  };

  const remove = (id: string) => {
    if (!window.confirm('Delete this punishment template?')) return;
    deletePunishmentTemplate(id);
    if (draft.id === id) clearForm();
    setMessage('Punishment template deleted.');
  };

  const triggerLabel = (trigger: PunishmentTrigger) =>
    trigger.type === 'quota_miss' ? 'Daily quota miss' : 'Manual';

  const list = (
    <>
      <AdminListHeader
        title="Punishments"
        count={filtered.length}
        search={search}
        onSearchChange={setSearch}
      />
      <p className="admin-list-intro muted">
        Applied when the daily quota is missed (up to 2 per day). Titles with
        &quot;bonus&quot; add an extra task.
      </p>
      <div className="admin-list">
        {filtered.length === 0 ? (
          <AdminEmpty
            title={search ? 'No matches' : 'No templates yet'}
            hint={
              search
                ? 'Try a different search term.'
                : 'Define templates that copy into active punishments.'
            }
          />
        ) : (
          filtered.map((t) => (
            <AdminItemCard
              key={t.id}
              selected={draft.id === t.id}
              title={t.title}
              meta={`−${t.pointsLost} pts · ${triggerLabel(t.trigger)}`}
              onEdit={() => {
                setDraft(t);
                setErrors({});
              }}
              onDelete={() => remove(t.id)}
            />
          ))
        )}
      </div>
    </>
  );

  const form = (
    <section className="card admin-form-card">
      <h3 className="admin-form-card__title">
        {draft.id ? 'Edit template' : 'New template'}
      </h3>
      <StatusBanner message={message} />

      <FormGroup legend="Basics">
        <FormField
          label="Title"
          htmlFor="pun-title"
          required
          error={errors.title}
        >
          <input
            id="pun-title"
            value={draft.title}
            onChange={(e) => {
              setDraft({ ...draft, title: e.target.value });
              if (errors.title) setErrors((p) => ({ ...p, title: '' }));
            }}
          />
        </FormField>
        <FormField label="Description" htmlFor="pun-desc">
          <textarea
            id="pun-desc"
            rows={3}
            value={draft.description}
            onChange={(e) =>
              setDraft({ ...draft, description: e.target.value })
            }
          />
        </FormField>
      </FormGroup>

      <FormGroup legend="Rules">
        <FormField label="Trigger" hint="When this template can be applied.">
          <RadioRow
            label="Punishment trigger"
            name="pun-trigger"
            options={[
              {
                value: 'quota_miss' as const,
                label: 'Quota miss',
                hint: 'Auto on missed daily quota',
              },
              {
                value: 'manual' as const,
                label: 'Manual',
                hint: 'Assigned by admin flow',
              },
            ]}
            value={draft.trigger.type}
            onChange={(type) =>
              setDraft({ ...draft, trigger: { type } as PunishmentTrigger })
            }
          />
        </FormField>
        <FormField label="Points lost" htmlFor="pun-points">
          <input
            id="pun-points"
            type="number"
            min={0}
            value={draft.pointsLost}
            onChange={(e) =>
              setDraft({ ...draft, pointsLost: Number(e.target.value) })
            }
          />
        </FormField>
      </FormGroup>

      <FormActions
        editing={!!draft.id}
        entityLabel="template"
        onSubmit={submit}
        onClear={() => {
          clearForm();
          setMessage('');
        }}
      />
    </section>
  );

  return <AdminPanel list={list} form={form} />;
}

function UserAdmin() {
  const { createAppUser } = useAppStore();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState<UserRole>('user');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  const submit = async () => {
    setError('');
    setMessage('');
    const result = await createAppUser(username, password, role);
    if (result.ok) {
      setMessage(`User "${result.user.username}" created.`);
      setUsername('');
      setPassword('');
    } else {
      setError(result.error);
    }
  };

  const form = (
    <section className="card admin-form-card">
      <h3 className="admin-form-card__title">New user</h3>
      <p className="muted admin-list-intro">
        Create accounts for regular users or additional admins.
      </p>
      <StatusBanner message={error} variant="err" />
      <StatusBanner message={message} />

      <FormGroup legend="Account">
        <FormField label="Username" htmlFor="user-name" required>
          <input
            id="user-name"
            autoComplete="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
        </FormField>
        <FormField
          label="Password"
          htmlFor="user-pass"
          hint="At least 6 characters."
          required
        >
          <input
            id="user-pass"
            type="password"
            autoComplete="new-password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
        </FormField>
        <FormField label="Role" htmlFor="user-role">
          <select
            id="user-role"
            value={role}
            onChange={(e) => setRole(e.target.value as UserRole)}
          >
            <option value="user">User</option>
            <option value="admin">Admin</option>
          </select>
        </FormField>
      </FormGroup>

      <FormActions
        editing={false}
        entityLabel="user"
        onSubmit={submit}
        onClear={() => {
          setUsername('');
          setPassword('');
          setRole('user');
          setMessage('');
          setError('');
        }}
      />
    </section>
  );

  return (
    <div className="admin-panel admin-panel--single">
      <div className="admin-panel__form">{form}</div>
    </div>
  );
}

